type Number interface{ ~int | ~int64 | ~float64 }   // the type set IS the trait

func Sum[T Number](xs []T) T {                     // + is legal for every type in the set
    var total T
    for _, x := range xs {
        total += x
    }
    return total
}

func Key[T comparable](v T) string { return fmt.Sprint(v) }   // == and map keys guaranteed

type Sizer interface{ Size() int }              // property = method set

func describe(v any) string {
    switch x := v.(type) {
    case Sizer:                    // discovered structurally, no registration
        return fmt.Sprintf("sized %d", x.Size())
    default:
        return "unknown"           // a type nobody described becomes "unknown"
    }
}

